import { test } from "node:test";
import assert from "node:assert/strict";
import { computeTotal, formatMoney } from "../src/orders.js";
import app from "../src/server.js";

test("total with tax", () => { assert.equal(computeTotal([{ price: 10, qty: 2 }]), 24); });
test("discount over 100", () => { assert.equal(computeTotal([{ price: 60, qty: 2 }]), 132); });
test("formatMoney", () => { assert.equal(formatMoney(3.5), "$3.50"); });
test("formatMoney thousands", () => { assert.equal(formatMoney(1234.5), "$1,234.50"); });

let server;
let base;

test("setup server", async () => {
  await new Promise((resolve) => {
    server = app.listen(0, () => {
      base = `http://127.0.0.1:${server.address().port}`;
      resolve();
    });
  });
});

test("POST /orders/validate — valid IBAN returns 200 valid:true", async () => {
  const res = await fetch(`${base}/orders/validate`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ recipient: "GB82WEST12345698765432" }),
  });
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body.valid, true);
});

test("POST /orders/validate — invalid IBAN returns 422 valid:false", async () => {
  const res = await fetch(`${base}/orders/validate`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ recipient: "NOTANIBAN" }),
  });
  assert.equal(res.status, 422);
  const body = await res.json();
  assert.equal(body.valid, false);
});

test("POST /orders/validate — missing recipient returns 400", async () => {
  const res = await fetch(`${base}/orders/validate`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({}),
  });
  assert.equal(res.status, 400);
  const body = await res.json();
  assert.equal(body.valid, false);
});

test("teardown server", async () => {
  await new Promise((resolve, reject) => server.close((err) => (err ? reject(err) : resolve())));
});

